## Cross-Platform Windowing

### Basic Window

```xiom
use xiom.glfw;

fn main() -> Int {
  glfw::init()?;

  let window = glfw::Window::new(800, 600, "XIOM App")?;
  window.make_context_current();

  while !window.should_close() {
    // Handle input
    if window.is_key_pressed(Key::Escape) {
      window.set_should_close(true);
    }

    // Render frame
    gl::clear(0.2, 0.3, 0.3, 1.0);

    window.swap_buffers();
    glfw::poll_events();
  }

  glfw::terminate();
  return 0;
}
```

### Input Handling

```xiom
// Keyboard
let keys = window.get_pressed_keys();
if keys.contains(Key::W) { camera.move_forward(); }
if keys.contains(Key::S) { camera.move_back(); }

// Mouse
let (x, y) = window.get_cursor_position();
let scroll = window.get_scroll_delta();

// Gamepad
if let Some(gamepad) = glfw::get_gamepad(0) {
  let left_stick = gamepad.get_axis(GamepadAxis::LeftX);
}

// Window events
window.on_resize(|width, height| {
  gl::viewport(0, 0, width, height);
});
```

### Window Hints (before creation)

```xiom
glfw::window_hint(Hint::Resizable, false);
glfw::window_hint(Hint::Samples, 4);  // MSAA
glfw::window_hint(Hint::ClientApi, ClientApi::Vulkan);
let window = glfw::Window::new(800, 600, "Vulkan App")?;
```

### Multiple Windows

```xiom
let main_window = glfw::Window::new(1024, 768, "Editor")?;
let preview_window = glfw::Window::new(320, 240, "Preview")?;

// Switch context to render to each
main_window.make_context_current();
render_scene();
preview_window.make_context_current();
render_preview();
```

### Timing

```xiom
let last_time = glfw::get_time();
while !window.should_close() {
  let current_time = glfw::get_time();
  let delta_time = current_time - last_time;
  last_time = current_time;

  update(delta_time);  // Frame-rate independent updates
  render();
}
```

